def reactions_for(message_id):
    c=connect(); rows=c.execute('SELECT emoji,user_id FROM reactions WHERE message_id=? ORDER BY rowid',(message_id,)).fetchall(); c.close()
    out=[]
    for r in rows:
        x=next((z for z in out if z['emoji']==r['emoji']),None)
