            core.add_workspace_member(c,inv['workspace_id'],request['user']['id'],'member')
        return web.json_response({'workspace':core.workspace_to_json(core.connect().execute('SELECT * FROM workspaces WHERE id=?',(inv['workspace_id'],)).fetchone())})
    w=core.get_workspace(request.match_info['slug'])
    if not w:return json_error(404,'workspace not found')
    role=core.member_role(w['id'],request['user']['id'])
    if request.method=='GET':
        if role not in ('owner','admin'):return json_error(403,'forbidden')
        c=core.connect();rs=c.execute('SELECT * FROM invitations WHERE workspace_id=? AND (expires_at IS NULL OR expires_at>?) AND uses<max_uses',(w['id'],__import__('time').time())).fetchall();c.close()
        return web.json_response({'invitations':[dict(r) for r in rs]})
    if role not in ('owner','admin'):return json_error(403,'forbidden')
    if request.method=='DELETE':
        with core.tx() as c:c.execute('DELETE FROM invitations WHERE workspace_id=? AND code=?',(w['id'],code))
        return web.json_response({'deleted':True})
    b=await read_json(request)
    if not b or any(k in b and not isinstance(b[k],int) for k in ('expires_in_seconds','max_uses')):return json_error(400,'invalid invitation')
    target=b.get('invited_user_id')
    if target is not None and not isinstance(target,int):return json_error(400,'invalid target')
    exp=__import__('time').time()+b['expires_in_seconds'] if b.get('expires_in_seconds') is not None else None
    uses=b.get('max_uses',1)
    if uses<1:return json_error(400,'invalid max_uses')
    code=__import__('secrets').token_urlsafe(12)
    with core.tx() as c:c.execute('INSERT INTO invitations(code,workspace_id,invited_user_id,expires_at,max_uses) VALUES(?,?,?,?,?)',(code,w['id'],target,exp,uses))
    return web.json_response({'invitation':{'code':code,'workspace_id':w['id'],'max_uses':uses,'uses':0}},status=201)
'''
